/**
 * @suppress
 */
public object FfiConverterTypeAppStateStore: FfiConverter<AppStateStore, Long> {
    override fun lower(value: AppStateStore): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): AppStateStore {
        return AppStateStore(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): AppStateStore {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: AppStateStore) = 8UL

    override fun write(value: AppStateStore, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


