/**
 * @suppress
 */
public object FfiConverterTypeWardenObject: FfiConverter<WardenObject, Long> {
    override fun lower(value: WardenObject): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): WardenObject {
        return WardenObject(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): WardenObject {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: WardenObject) = 8UL

    override fun write(value: WardenObject, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
