/**
 * THE WARDEN typed failure-reason surface (D27 — the QUARTET's `WardenError`, promised in `Cargo.toml:47`
 * but previously phantom; now the real 4th `uniffi::Error` beside `FortressError`/`CentauriError`/
 * `MaskSolverError`). It names WHY a domain rule was refused by the RFC-1123 integrity gate
 * ([`super::pattern::validate_pattern`], the poisoned-blocklist defense): the UI's add-rule pre-flight
 * ([`warden_validate_pattern`]) throws it so a user learns exactly why a rule was rejected instead of it
 * silently vanishing — the crate's error-handling standard applied to the security surface. Each variant
 * mirrors a [`super::pattern::MalformedPattern`]; the `From` below is the single mapping point.
 */
sealed class WardenException: kotlin.Exception() {
    
    /**
     * The pattern is empty (all whitespace / all empty labels).
     */
    class Empty(
        ) : WardenException() {
        override val message
            get() = ""
    }
    
    /**
     * The pattern exceeds the max DNS name length (253).
     */
    class TooLong(
        ) : WardenException() {
        override val message
            get() = ""
    }
    
    /**
     * Fewer than two labels — a bare TLD like `com` (the over-broad nuke).
     */
    class TooFewLabels(
        ) : WardenException() {
        override val message
            get() = ""
    }
    
    /**
     * A label is empty (a `..` in the middle — malformed).
     */
    class EmptyLabel(
        ) : WardenException() {
        override val message
            get() = ""
    }
    
    /**
     * A label exceeds the max label length (63).
     */
    class LabelTooLong(
        ) : WardenException() {
        override val message
            get() = ""
    }
    
    /**
     * A label carries a byte outside `[a-z0-9-*]` (after canonicalization).
     */
    class BadChar(
        
        /**
         * The offending character (as a string — `char` for FFI simplicity).
         */
        val `ch`: kotlin.String
        ) : WardenException() {
        override val message
            get() = "ch=${ `ch` }"
    }
    
    /**
     * A label begins or ends with a hyphen (RFC-1123).
     */
    class LeadingOrTrailingHyphen(
        ) : WardenException() {
        override val message
            get() = ""
    }
    
    /**
     * A label carries more than the permitted wildcards (an over-broad saturated label).
     */
    class TooManyWildcards(
        ) : WardenException() {
        override val message
            get() = ""
    }
    
    /**
     * Fewer than two trailing LITERAL labels (e.g. `*.com`) — the over-broad pattern the gate refuses.
     */
    class OverBroad(
        ) : WardenException() {
        override val message
            get() = ""
    }
    
    /**
     * The final label is all-numeric (an IP-shaped pseudo-TLD, never a real domain).
     */
    class NumericTld(
        ) : WardenException() {
        override val message
            get() = ""
    }
    
    /**
     * A panic inside the bridge — the `catch_unwind` firewall caught a bug and reports it as a typed
     * error, never an abort across the FFI boundary. Never expected (validation is panic-free); kept so
     * the contract is total (the `MaskSolverError::Panic` precedent).
     */
    class Panic(
        
        /**
         * A short description of the caught panic.
         */
        val `reason`: kotlin.String
        ) : WardenException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<WardenException> {
        override fun lift(error_buf: RustBuffer.ByValue): WardenException = FfiConverterTypeWardenError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeWardenError : FfiConverterRustBuffer<WardenException> {
    override fun read(buf: ByteBuffer): WardenException {
        

        return when(buf.getInt()) {
            1 -> WardenException.Empty()
            2 -> WardenException.TooLong()
            3 -> WardenException.TooFewLabels()
            4 -> WardenException.EmptyLabel()
            5 -> WardenException.LabelTooLong()
            6 -> WardenException.BadChar(
                FfiConverterString.read(buf),
                )
            7 -> WardenException.LeadingOrTrailingHyphen()
            8 -> WardenException.TooManyWildcards()
            9 -> WardenException.OverBroad()
            10 -> WardenException.NumericTld()
            11 -> WardenException.Panic(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: WardenException): ULong {
        return when(value) {
            is WardenException.Empty -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WardenException.TooLong -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WardenException.TooFewLabels -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WardenException.EmptyLabel -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WardenException.LabelTooLong -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WardenException.BadChar -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`ch`)
            )
            is WardenException.LeadingOrTrailingHyphen -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WardenException.TooManyWildcards -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WardenException.OverBroad -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WardenException.NumericTld -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is WardenException.Panic -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: WardenException, buf: ByteBuffer) {
        when(value) {
            is WardenException.Empty -> {
                buf.putInt(1)
                Unit
            }
            is WardenException.TooLong -> {
                buf.putInt(2)
                Unit
            }
            is WardenException.TooFewLabels -> {
                buf.putInt(3)
                Unit
            }
            is WardenException.EmptyLabel -> {
                buf.putInt(4)
                Unit
            }
            is WardenException.LabelTooLong -> {
                buf.putInt(5)
                Unit
            }
            is WardenException.BadChar -> {
                buf.putInt(6)
                FfiConverterString.write(value.`ch`, buf)
                Unit
            }
            is WardenException.LeadingOrTrailingHyphen -> {
                buf.putInt(7)
                Unit
            }
            is WardenException.TooManyWildcards -> {
                buf.putInt(8)
                Unit
            }
            is WardenException.OverBroad -> {
                buf.putInt(9)
                Unit
            }
            is WardenException.NumericTld -> {
                buf.putInt(10)
                Unit
            }
            is WardenException.Panic -> {
                buf.putInt(11)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



